from pathlib import Path
import json,html
ROOT=Path("research/echecs_2026/atlas_v3/results")
WEB=Path("docs/echecs-atlas");WEB.mkdir(parents=True,exist_ok=True)
def read(name,default):
 p=ROOT/name
 return json.loads(p.read_text(encoding="utf-8")) if p.exists() else default
data={k:read(v,[] if k!="summary" else {}) for k,v in {
 "events":"events.json","players":"players.json","delegations":"delegations.json","pairs":"coappearances.json","communities":"communities.json","funding":"funding.json","summary":"summary.json"
}.items()}
payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
template=r"""<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Atlas des échecs français — personnes, lieux, dates, organisations</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--side:#10192a;--panel:#172238;--stroke:#30425b;--ink:#e6effa;--muted:#a5b5cc;--blue:#76b9ff;--gold:#dfbd80;--green:#7adbb5}*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:1px solid var(--stroke);color:var(--ink);background:#1e304b;border-radius:9px;padding:8px 12px}button:hover,.active{border-color:var(--blue);background:#244260}.wrap{max-width:1580px;margin:auto;padding:24px}.eyebrow{font:700 11px/1.5 system-ui;letter-spacing:.14em;color:var(--blue);text-transform:uppercase}h1{font-weight:720;letter-spacing:-.04em;font-size:clamp(27px,4vw,48px);line-height:1.1;margin:9px 0}h2{font-size:18px;letter-spacing:-.015em;margin:0 0 12px}p{color:var(--muted);margin:4px 0 12px}a{color:#b1d7ff;text-decoration:none}a:hover{text-decoration:underline}
.top{display:flex;align-items:end;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:0 0 20px;border-bottom:1px solid var(--stroke)}.hint{font-size:12px;max-width:580px}.metrics{display:grid;grid-template-columns:repeat(5,minmax(100px,1fr));gap:9px;margin:20px 0}.metric{padding:14px 16px;background:var(--side);border:1px solid var(--stroke);border-radius:13px}.metric strong{display:block;font-size:24px;letter-spacing:-.04em;font-variant-numeric:tabular-nums}.metric span{font-size:12px;color:var(--muted)}
.controls{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.controls input,.controls select{background:#0c1525;border:1px solid var(--stroke);border-radius:9px;color:var(--ink);padding:10px 12px;min-width:135px}.controls input{flex:1;min-width:220px}
.layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,.95fr);gap:14px}.panel{background:var(--side);border:1px solid var(--stroke);border-radius:14px;padding:17px;min-width:0}.plot{position:relative;height:490px;border-radius:10px;background:radial-gradient(circle at 30% 30%,#1b2c47,#090f1d 72%);overflow:hidden}canvas{width:100%;height:100%;display:block;touch-action:none}.legend{display:flex;flex-wrap:wrap;gap:10px;font-size:11px;color:var(--muted);margin:10px 0}.dot{width:9px;height:9px;border-radius:100%;display:inline-block;margin-right:4px}.dataTable{width:100%;border-collapse:collapse;font-size:12px}.dataTable td,.dataTable th{padding:9px 8px;text-align:left;border-bottom:1px solid #2c3850;vertical-align:top}.dataTable th{color:var(--muted);font-weight:600}.scroll{max-height:450px;overflow:auto}.chips{display:flex;flex-wrap:wrap;gap:8px}.chip{font-size:11px;background:#20334f;color:#c6def7;padding:4px 9px;border-radius:12px}.micro{font-size:11px;color:var(--muted)}.stateline{margin:10px 0;border-top:1px solid var(--stroke);padding-top:11px}.tabs{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:12px}.bars{display:flex;align-items:flex-end;height:180px;gap:10px;border-bottom:1px solid var(--stroke)}.barcol{flex:1;display:flex;flex-direction:column;justify-content:end;height:100%;align-items:center;font-size:11px;color:var(--muted)}.bar{width:100%;max-width:55px;background:linear-gradient(180deg,#84c8fa,#315a9f);border-radius:5px 5px 0 0;min-height:2px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.callout{border-left:3px solid var(--gold);background:#1d2432;border-radius:5px;padding:11px;color:#dce5ef;font-size:12px;margin-top:12px}.footer{padding:24px 0;color:var(--muted);font-size:12px}.empty{padding:30px;text-align:center;color:var(--muted)}code{color:#d5eaff} .resultbtn{text-align:left;width:100%;background:transparent;margin:3px 0;border:0;border-bottom:1px solid #2a3a52;border-radius:0}.resultbtn:hover{background:#1b2e49} .num{color:var(--gold);font-weight:bold} .spaced{margin-top:16px}
@media(max-width:900px){.layout,.cols{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.plot{height:380px}.wrap{padding:14px}.metric strong{font-size:21px}}
</style></head><body>
<div class="wrap">
 <header class="top"><div><div class="eyebrow">Observatoire documentaire • France • 2022–2026</div><h1>Atlas des échecs français</h1><p>Personnes, tournois, lieux, clubs, responsabilités et flux publics — une exploration factuelle des réseaux.</p></div><p class="hint">L'apparition commune dans un tournoi signifie seulement une co-présence sportive publiée. Elle ne prouve ni proximité personnelle, ni transaction financière, ni irrégularité. Les jeunes ne font pas l'objet d'un suivi nominatif longitudinal.</p></header>
 <section id="metrics" class="metrics"></section>
 <nav class="controls"><input id="q" placeholder="Chercher une personne, un club, un tournoi, une ville…"><select id="year"><option value="">Toutes les années</option><option>2022</option><option>2023</option><option>2024</option><option>2025</option><option>2026</option></select><select id="type"><option value="">Tous les acteurs</option><option value="PERSON:">Joueurs adultes</option><option value="CLUB:">Clubs</option><option value="ARBITER:">Arbitres</option><option value="ORGANIZER:">Organisateurs</option></select><button id="reset">Réinitialiser</button></nav>
 <div class="tabs"><button class="active" data-mode="network">Réseau des co-présences</button><button data-mode="timeline">Chronologie</button><button data-mode="communities">Communautés</button><button data-mode="funding">Financements</button><button data-mode="events">Tournois</button></div>
 <div class="layout"><section class="panel"><h2 id="paneTitle">Liens documentés et répétitions</h2><div id="main"></div></section><aside class="panel"><h2 id="sideTitle">Explorer les connexions</h2><div id="detail"><p>Recherche un nom ou clique sur un nœud pour afficher les événements exacts, les dates, les clubs et les sources.</p></div></aside></div>
 <div class="cols"><section class="panel"><h2>Co-présences récurrentes dans le corpus</h2><p class="micro">Comptage de tournois distincts, et non nombre de rondes ou de parties ; les très grands opens ne doivent pas être interprétés comme des relations personnelles.</p><div id="ranked" class="scroll"></div></section><section class="panel"><h2>Couverture, méthode et limites</h2><div id="provenance"></div></section></div>
 <footer class="footer">Atlas documentaire produit à partir de pages fédérales et de données publiques de l'État. Chaque tournoi renvoie à sa fiche officielle. Les rapprochements d'identité par nom demeurent provisoires sans identifiant stable ; les montants publics sont séparés des co-présences sportives.</footer>
</div>
<script id="atlas-data" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.getElementById("atlas-data").textContent),E=new Map(D.events.map(e=>[e.ref,e])),actor=new Map(), refs=new Map(),els={main:document.getElementById("main"),detail:document.getElementById("detail"),ranked:document.getElementById("ranked")};
const S={mode:"network",query:"",year:"",type:"",focus:""};const h=s=>String(s??"").replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const pretty=id=>actor.get(id)?.label||id.split(":").slice(1).join(":");
function add(id,label,ref,kind){if(!id)return;let a=actor.get(id);if(!a){a={id,label,kind,refs:new Set()};actor.set(id,a)}if(ref)a.refs.add(ref);}
D.events.forEach(e=>{add("ORGANIZER:"+(e.organizer||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Z0-9 ]/gi," ").toUpperCase().replace(/\s+/g," ").trim(),e.organizer,e.ref,"organizer");add("ARBITER:"+(e.arbiter||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Z0-9 ]/gi," ").toUpperCase().replace(/\s+/g," ").trim(),e.arbiter,e.ref,"arbiter")});
D.players.forEach(p=>add("PERSON:"+p.key,p.name,p.ref,"player"));D.delegations.forEach(c=>add("CLUB:"+c.club_key,c.club,c.ref,"club"));
let A=[...actor.values()].filter(x=>x.label);
const filtered=e=>!S.year||String(e.year)===S.year;
const match=a=>(!S.type||a.id.startsWith(S.type))&&(!S.year||[...a.refs].some(id=>filtered(E.get(id)||{})))&&(!S.query||a.label.toLowerCase().includes(S.query.toLowerCase()));
const evLink=(ref)=>{let e=E.get(ref);return e?'<a href="'+h(e.url)+'" target="_blank" rel="noopener">'+h(e.title)+' · '+h(e.town)+' · '+h(e.date||e.year)+'</a>':""};
const color=id=>id.startsWith("PERSON:")?"#75bdff":id.startsWith("CLUB:")?"#7fdfb2":id.startsWith("ARBITER:")?"#e8bd77":"#c39cfa";
const peopleForRef=ref=>D.players.filter(p=>p.ref===ref);
function renderMetrics(){let m=D.summary;document.getElementById("metrics").innerHTML=[["Index national (1res pages)",m.index_tournaments||0],["Fiches enrichies",m.metadata_events||0],["Participations adultes",m.named_adult_participations||0],["Délégations de clubs",m.club_delegations||0],["Paires récurrentes",m.repeated_pairs||0]].map(([k,v])=>'<div class="metric"><strong>'+Number(v).toLocaleString("fr-FR")+'</strong><span>'+h(k)+'</span></div>').join("")}
function focus(id){S.focus=id;let a=actor.get(id);if(!a)return;let ev=[...a.refs].map(ref=>E.get(ref)).filter(Boolean).sort((x,y)=>(y.date||"").localeCompare(x.date||""));let ties=D.pairs.filter(p=>p.a===id||p.b===id).slice(0,25);
document.getElementById("sideTitle").textContent="Profil documentaire";
els.detail.innerHTML='<div class="eyebrow">'+h(a.kind)+'</div><h2>'+h(a.label)+'</h2><p>'+ev.length+' tournoi(s) présent(s) dans la couche analysée. Ceci ne décrit pas tous ses engagements.</p><div class="chips">'+[...new Set(ev.map(e=>e.town).filter(Boolean))].slice(0,12).map(x=>'<span class="chip">'+h(x)+'</span>').join("")+'</div><div class="stateline"><strong>Événements datés</strong><div class="scroll">'+ev.slice(0,55).map(e=>'<div class="stateline">'+evLink(e.ref)+'<p class="micro">Organisation : '+h(e.organizer)+' · Arbitrage : '+h(e.arbiter)+'</p></div>').join("")+'</div></div>'+(ties.length?'<div class="stateline"><strong>Autres acteurs récurrents</strong>'+ties.map(x=>'<button class="resultbtn" data-focus="'+h(x.a===id?x.b:x.a)+'">'+h(pretty(x.a===id?x.b:x.a))+' · '+x.n+' événement(s)</button>').join("")+'</div>':'');
bindFocus();}
function bindFocus(){document.querySelectorAll("[data-focus]").forEach(b=>b.addEventListener("click",()=>{focus(b.dataset.focus)}))}
let canvas,ctx,nodes=[],links=[],width,height,mouse={drag:null,hover:null};
function graph(){
 const pair=D.pairs.filter(p=>(!S.year||p.years.map(String).includes(S.year))&&(!S.type||p.a.startsWith(S.type)||p.b.startsWith(S.type))&&(!S.query||pretty(p.a).toLowerCase().includes(S.query.toLowerCase())||pretty(p.b).toLowerCase().includes(S.query.toLowerCase()))).slice(0,185);
 const weight=new Map();pair.forEach(p=>{weight.set(p.a,(weight.get(p.a)||0)+p.n);weight.set(p.b,(weight.get(p.b)||0)+p.n)});
 const chosen=[...weight].sort((a,b)=>b[1]-a[1]).slice(0,75).map(x=>x[0]);const keep=new Set(chosen);
 nodes=chosen.map((id,i)=>({id,label:pretty(id),x:300+150*Math.cos(i*2.399),y:220+140*Math.sin(i*2.399),vx:0,vy:0,r:5+Math.min(11,Math.sqrt(weight.get(id)||1)*1.8)}));
 const lookup=new Map(nodes.map((n,i)=>[n.id,i]));links=pair.filter(p=>keep.has(p.a)&&keep.has(p.b)).map(p=>({a:lookup.get(p.a),b:lookup.get(p.b),n:p.n}));
 els.main.innerHTML='<div class="plot"><canvas id="network-canvas" aria-label="Graphe des acteurs et des événements récurrents"></canvas></div><div class="legend"><span><i class="dot" style="background:#75bdff"></i>Joueurs adultes</span><span><i class="dot" style="background:#7fdfb2"></i>Clubs</span><span><i class="dot" style="background:#e8bd77"></i>Arbitres</span><span><i class="dot" style="background:#c39cfa"></i>Organisateurs</span></div><p class="micro">Nœuds : acteurs issus du corpus. Traits : au moins deux tournois communs ; épaisseur proportionnelle au nombre de co-présences. Graphe borné aux 75 acteurs les plus connectés du filtre.</p>';
 canvas=document.getElementById("network-canvas");ctx=canvas.getContext("2d");function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;canvas.width=Math.ceil(width*devicePixelRatio);canvas.height=Math.ceil(height*devicePixelRatio);ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}resize();
 canvas.onpointermove=e=>{let p=getpos(e);if(mouse.drag){mouse.drag.x=p.x;mouse.drag.y=p.y;mouse.drag.vx=mouse.drag.vy=0}mouse.hover=nodes.find(n=>Math.hypot(n.x-p.x,n.y-p.y)<n.r+5)||null;canvas.style.cursor=mouse.hover?"pointer":"grab"};
 canvas.onpointerdown=e=>{let p=getpos(e);mouse.drag=nodes.find(n=>Math.hypot(n.x-p.x,n.y-p.y)<n.r+5)||null;canvas.setPointerCapture(e.pointerId)};canvas.onpointerup=e=>{if(mouse.drag){focus(mouse.drag.id);mouse.drag=null}};function getpos(e){let r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top}}
 let rounds=0;function step(){if(!canvas||!canvas.isConnected)return;rounds++;if(rounds<300){for(let i=0;i<nodes.length;i++){let a=nodes[i];a.vx+=(width/2-a.x)*.0008;a.vy+=(height/2-a.y)*.0008;for(let j=i+1;j<nodes.length;j++){let b=nodes[j],dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy+1,k=480/d2;a.vx+=dx*k;a.vy+=dy*k;b.vx-=dx*k;b.vy-=dy*k}}for(let l of links){let a=nodes[l.a],b=nodes[l.b],dx=b.x-a.x,dy=b.y-a.y,dist=Math.hypot(dx,dy)||1,k=(dist-100)*.0006;a.vx+=dx*k;a.vy+=dy*k;b.vx-=dx*k;b.vy-=dy*k}for(let n of nodes){if(n===mouse.drag)continue;n.vx*=.78;n.vy*=.78;n.x=Math.max(15,Math.min(width-15,n.x+n.vx));n.y=Math.max(15,Math.min(height-15,n.y+n.vy))}}
 ctx.clearRect(0,0,width,height);links.forEach(l=>{let a=nodes[l.a],b=nodes[l.b];ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle="rgba(125,171,226,.2)";ctx.lineWidth=.55+Math.log2(l.n+1);ctx.stroke()});nodes.forEach(n=>{ctx.beginPath();ctx.arc(n.x,n.y,n.r,0,Math.PI*2);ctx.fillStyle=color(n.id);ctx.fill();ctx.strokeStyle="#112034";ctx.lineWidth=2;ctx.stroke();if(n===mouse.hover||n.id===S.focus||n.r>12){ctx.fillStyle="#e8f2ff";ctx.font="11px system-ui";ctx.fillText(n.label.slice(0,26),n.x+n.r+4,n.y+4)}});requestAnimationFrame(step)}step();
}
function showTimeline(){let ev=D.events.filter(filtered).filter(e=>!S.query||[e.title,e.town,e.organizer,e.arbiter].join(' ').toLowerCase().includes(S.query.toLowerCase()));let ys=[2022,2023,2024,2025,2026],counts=ys.map(y=>ev.filter(e=>e.year===y).length),top=Math.max(1,...counts);els.main.innerHTML='<p>Nombre de fiches enrichies par année (échantillon, pas volume national).</p><div class="bars">'+ys.map((y,i)=>'<div class="barcol"><b>'+counts[i]+'</b><div class="bar" style="height:'+(counts[i]/top*135)+'px"></div><span>'+y+'</span></div>').join("")+'</div><h2 class="spaced">Événements correspondants</h2><div class="scroll">'+ev.slice(0,120).map(e=>'<div class="stateline">'+evLink(e.ref)+'<p class="micro">Organisation : '+h(e.organizer)+' · Arbitre : '+h(e.arbiter)+'</p></div>').join("")+'</div>'}
function showCommunities(){els.main.innerHTML='<p>Communautés détectées par l’algorithme Louvain sur les co-présences répétées. Il s’agit de regroupements statistiques, pas de cercles privés prouvés.</p>'+D.communities.slice(0,25).map(c=>'<div class="stateline"><strong>Cluster '+c.id+' · '+c.size+' acteurs · '+c.edges+' relations</strong><div class="chips">'+c.members.slice(0,20).map(m=>'<button data-focus="'+h(m.id)+'">'+h(m.label)+' <small>'+m.links+'</small></button>').join('')+'</div></div>').join('');bindFocus()}
function showFunding(){const rows=D.funding.slice().sort((a,b)=>b.amount-a.amount);let total=rows.reduce((n,r)=>n+r.amount,0);els.main.innerHTML='<p>Flux d’État explicitement documentés dans l’annexe PLF 2025 (versements 2023). <strong>'+rows.length+'</strong> lignes, <strong>'+Math.round(total).toLocaleString('fr-FR')+' €</strong>. Ils ne sont pas imputables à un événement sans convention ou comptabilité spécifique.</p><div class="scroll"><table class="dataTable"><tr><th>Organisme</th><th>Programme</th><th>Montant</th></tr>'+rows.slice(0,220).map(r=>'<tr><td>'+h(r.name)+'</td><td>'+h(r.program)+'</td><td class="num">'+Math.round(r.amount).toLocaleString('fr-FR')+' €</td></tr>').join('')+'</table></div>'}
function showEvents(){let ee=D.events.filter(filtered).filter(e=>!S.query||[e.title,e.town,e.organizer,e.arbiter].join(' ').toLowerCase().includes(S.query.toLowerCase()));els.main.innerHTML='<p>'+ee.length+' fiches événement dans le filtre courant.</p><div class="scroll"><table class="dataTable"><tr><th>Date</th><th>Compétition et lieu</th><th>Organisateur</th><th>Arbitre</th></tr>'+ee.slice(0,280).map(e=>'<tr><td>'+h(e.date||e.year)+'</td><td>'+evLink(e.ref)+'</td><td>'+h(e.organizer)+'</td><td>'+h(e.arbiter)+'</td></tr>').join('')+'</table></div>'}
function showRanked(){els.ranked.innerHTML=D.pairs.filter(p=>(!S.year||p.years.map(String).includes(S.year))&&(!S.query||pretty(p.a).toLowerCase().includes(S.query.toLowerCase())||pretty(p.b).toLowerCase().includes(S.query.toLowerCase()))).slice(0,90).map(p=>'<div class="stateline"><button class="resultbtn" data-focus="'+h(p.a)+'">'+h(pretty(p.a))+'</button><span class="micro">avec</span><button class="resultbtn" data-focus="'+h(p.b)+'">'+h(pretty(p.b))+'</button><b class="num">'+p.n+' événements</b><p class="micro">'+h(p.years.join(' / '))+' · '+p.refs.slice(0,4).map(id=>'<a href="'+h(E.get(id)?.url||'#')+'" target="_blank">#'+id+'</a>').join(' · ')+'</p></div>').join('')||'<p>Aucune paire récurrente dans le filtre.</p>';bindFocus()}
function provenance(){let s=D.summary;document.getElementById("provenance").innerHTML='<p>Extraction horodatée : '+h(s.generated)+'</p><div class="chips"><span class="chip">'+s.departments+' départements interrogés</span><span class="chip">'+s.roster_pages+' listes de participants consultées</span><span class="chip">'+s.rosters_with_players+' tableaux exploitables</span></div><div class="callout">Couverture non exhaustive : les index départementaux ne contiennent ici que leur première page. Les tournois et joueurs sont enrichis par sélection. Les pages de résultats comportent parfois des données de jeunes, exploitées uniquement en comptages agrégés par club.</div><p class="spaced">Une similarité de nom n’identifie pas une personne. Les relations sont liées à des références de tournois et datées. Une co-présence ne vaut pas rencontre ni connaissance réciproque.</p><p>Financements : la couche budgétaire porte sur 2023 et est distincte des événements 2022–2026.</p>'}
function render(){document.getElementById("paneTitle").textContent={network:"Réseau des co-présences",timeline:"Chronologie des compétitions",communities:"Clusters détectés",funding:"Flux budgétaires publiés",events:"Catalogue des événements"}[S.mode];if(S.mode==='network')graph();else if(S.mode==='timeline')showTimeline();else if(S.mode==='communities')showCommunities();else if(S.mode==='funding')showFunding();else showEvents();showRanked()}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{S.mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));render()});document.getElementById('q').oninput=e=>{S.query=e.target.value;render();let matches=A.filter(match).sort((a,b)=>b.refs.size-a.refs.size);if(matches.length)focus(matches[0].id)};document.getElementById('year').onchange=e=>{S.year=e.target.value;render()};document.getElementById('type').onchange=e=>{S.type=e.target.value;render()};document.getElementById('reset').onclick=()=>{S.query=S.year=S.type=S.focus='';document.getElementById('q').value='';document.getElementById('year').value='';document.getElementById('type').value='';render();document.getElementById("sideTitle").textContent="Explorer les connexions";els.detail.innerHTML='<p>Clique sur un nœud ou cherche une personne, un club, une ville.</p>'};
renderMetrics();provenance();render();
</script></body></html>"""
(WEB/"index.html").write_text(template.replace("__DATA__",payload),encoding="utf-8")
print("WEB",WEB/"index.html","bytes",(WEB/"index.html").stat().st_size)
